+/** Theoretical use from sales vs. actual consume movements between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === sale.dishId);
+    if (!dish) continue;
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, sale.qty)) {
+      theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const ids = new Set([...theoretical.keys(), ...actual.keys()]);
+  const lines = [];
+  for (const itemId of [...ids].sort((a, b) => a - b)) {
+    const t = Math.round((theoretical.get(itemId) ?? 0) * 1000) / 1000;
+    const a = Math.round((actual.get(itemId) ?? 0) * 1000) / 1000;
+    if (t <= 0 && a <= 0) continue;
+    const item = store.data.items.find((i) => i.id === itemId);
+    lines.push({
+      itemId,
+      name: item ? item.name : "",
+      theoretical: t,
+      actual: a,
+      difference: Math.round((a - t) * 1000) / 1000,
+    });
+  }
+  return lines;
+}
