diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..1f4231c
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,77 @@
+// Importing sales from the till (ticket,soldAt,dishId,qty).
+// Each dish sold uses one recipe portion per qty, with ledger ref sale:<ticket>.
+// Already-imported tickets are skipped; any invalid row or shortfall aborts the whole file.
+import { AppError } from "../errors.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function isIsoInstant(s) {
+  return typeof s === "string" && /^\d{4}-\d{2}-\d{2}T/.test(s) && !Number.isNaN(Date.parse(s));
+}
+
+/** Imports sales CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `${where}: missing column ${k}` });
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isIsoInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${r.dishId}` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return {
+      where,
+      ticket: r.ticket,
+      soldAt: new Date(r.soldAt).toISOString(),
+      dishId,
+      dish,
+      qty,
+    };
+  });
+
+  const importedTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const toImport = clean.filter((r) => !importedTickets.has(r.ticket));
+
+  const remaining = new Map();
+  for (const r of toImport) {
+    const recipe = getRecipe(store, r.dish.recipeId);
+    for (const n of scaled(recipe, r.qty)) {
+      if (!remaining.has(n.itemId)) remaining.set(n.itemId, onHand(store, n.itemId));
+      const available = remaining.get(n.itemId);
+      if (available < n.qty) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("not_enough_stock_row", { where: r.where, item: item.name, available, unit: item.unit });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const newTickets = new Set();
+  let dishes = 0;
+  for (const r of toImport) {
+    const recipe = getRecipe(store, r.dish.recipeId);
+    for (const n of scaled(recipe, r.qty)) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: r.ticket,
+      soldAt: r.soldAt,
+      dishId: r.dishId,
+      qty: r.qty,
+    });
+    newTickets.add(r.ticket);
+    dishes += r.qty;
+  }
+
+  return { tickets: newTickets.size, dishes };
+}
